#!/usr/bin/env python3
"""
Run this script in the root of your portfolio repo (same folder as index.html):
    python3 patch_cansat_results.py

What it does:
  - Adds CSS for competition photo overlays
  - Inserts a "CanSat 2026 Competition Results" section with your 5 photos + scoresheet
  - Adds JavaScript for the lightbox
  All images are embedded as base64 data URIs (no extra files needed).
"""
import sys

try:
    with open('index.html', 'r', encoding='utf-8') as f:
        html = f.read()
except FileNotFoundError:
    print("ERROR: index.html not found. Run this script in the portfolio root folder.")
    sys.exit(1)

if '<!-- COMPETITION RESULTS -->' in html:
    print("index.html is already patched. Nothing to do.")
    sys.exit(0)

COMP_CSS = '\n  /* Competition photo overlays */\n  .comp-photo-wrap img { transition: opacity 0.2s; }\n  .comp-photo-wrap:hover img { opacity: 0.82; }\n  .comp-photo-overlay {\n    position: absolute; inset: 0;\n    display: flex; align-items: flex-end;\n    background: linear-gradient(to top, rgba(10,10,10,0.72) 0%, transparent 55%);\n    opacity: 0; transition: opacity 0.2s;\n    pointer-events: none;\n  }\n  .comp-photo-wrap:hover .comp-photo-overlay { opacity: 1; }\n  .comp-photo-label {\n    padding: 12px 14px;\n    font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase;\n    color: var(--accent); line-height: 1.4;\n    font-family: var(--mono);\n  }\n  @media (max-width: 900px) {\n    #competition-results { padding-left: 24px !important; padding-right: 24px !important; }\n  }\n'

COMP_SECTION = '\n<!-- COMPETITION RESULTS -->\n<section id="competition-results" style="padding: 80px 48px; border-bottom: 0.5px solid var(--line); background: var(--bg2);">\n  <div class="section-header">\n    <span class="section-num" style="font-size: 14px;">★</span>\n    <h2>CanSat 2026 – Competition Results</h2>\n    <div class="section-line"></div>\n  </div>\n\n  <div style="display: flex; align-items: flex-start; gap: 40px; flex-wrap: wrap; margin-bottom: 56px;">\n    <div style="border: 0.5px solid var(--accent2); background: var(--accent-dim); padding: 28px 40px; display: flex; flex-direction: column; gap: 6px; flex-shrink: 0;">\n      <span style="font-size: 10px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--accent);">Final Placement</span>\n      <span style="font-family: var(--display); font-size: 56px; font-weight: 800; line-height: 1; color: var(--text); letter-spacing: -0.03em;">14<sup style="font-size: 26px; color: var(--accent2); vertical-align: super; letter-spacing: 0;">th</sup></span>\n      <span style="font-size: 11px; color: var(--muted); letter-spacing: 0.06em;">out of 36 international teams</span>\n    </div>\n    <div style="border: 0.5px solid var(--accent2); background: var(--accent-dim); padding: 28px 40px; display: flex; flex-direction: column; gap: 6px; flex-shrink: 0;">\n      <span style="font-size: 10px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--accent);">Final Score</span>\n      <span style="font-family: var(--display); font-size: 56px; font-weight: 800; line-height: 1; color: var(--text); letter-spacing: -0.03em;">78.18<sup style="font-size: 22px; color: var(--accent2); vertical-align: super; letter-spacing: 0;">%</sup></span>\n      <span style="font-size: 11px; color: var(--muted); letter-spacing: 0.06em;">Team 1049 · Germany</span>\n    </div>\n    <div style="flex: 1; min-width: 260px; padding-top: 8px;">\n      <p style="font-size: 12px; color: var(--muted); line-height: 1.9;">Team Skybound (SRH Berlin) competed against 36 international teams at the 2026 CanSat Competition in Monterey, Virginia, placing <strong style="color: var(--text);">14th globally</strong> with a final score of 78.18%. Representing Germany as the only German university team, we placed ahead of teams from the US, Italy, Korea, Singapore, Colombia, and 20+ other nations — top 40% in a NASA/NRL-sponsored international competition.</p>\n    </div>\n  </div>\n\n  <div style="display: grid; grid-template-columns: repeat(12, 1fr); gap: 8px; margin-bottom: 12px;">\n    <div style="grid-column: 1 / 8; grid-row: 1 / 3; position: relative; cursor: pointer; overflow: hidden;" class="comp-photo-wrap" data-comp-index="0">\n      <img src="data:image/jpeg;base64," alt="Team Skybound at CanSat 2026 in front of the American Astronautical Society backdrop, holding the CanSat hardware and German flag" style="width:100%; height:100%; min-height:260px; object-fit:cover; display:block; border: 0.5px solid var(--line);">\n      <div class="comp-photo-overlay"><span class="comp-photo-label">Team Skybound · AAS, Monterey Virginia</span></div>\n    </div>\n    <div style="grid-column: 8 / 13; grid-row: 1; position: relative; cursor: pointer; overflow: hidden;" class="comp-photo-wrap" data-comp-index="1">\n      <img src="data:image/jpeg;base64," alt="Skybound ground station case open showing paraglider canopy, orange CanSat shell, and telemetry dashboard" style="width:100%; aspect-ratio:16/9; object-fit:cover; display:block; border: 0.5px solid var(--line);">\n      <div class="comp-photo-overlay"><span class="comp-photo-label">Ground Station · Pre-flight</span></div>\n    </div>\n    <div style="grid-column: 8 / 13; grid-row: 2; position: relative; cursor: pointer; overflow: hidden;" class="comp-photo-wrap" data-comp-index="2">\n      <img src="data:image/jpeg;base64," alt="Field operations table with orange CanSat shell, ground station laptop, and avionics on launch day" style="width:100%; aspect-ratio:16/9; object-fit:cover; display:block; border: 0.5px solid var(--line);">\n      <div class="comp-photo-overlay"><span class="comp-photo-label">Field Ops · Launch Day</span></div>\n    </div>\n    <div style="grid-column: 1 / 7; grid-row: 3; position: relative; cursor: pointer; overflow: hidden;" class="comp-photo-wrap" data-comp-index="3">\n      <img src="data:image/jpeg;base64," alt="Post-flight hardware: orange SRH CanSat container, exposed avionics frame, and deployed paraglider canopy" style="width:100%; aspect-ratio:16/9; object-fit:cover; display:block; border: 0.5px solid var(--line);">\n      <div class="comp-photo-overlay"><span class="comp-photo-label">Post-flight Hardware · After Recovery</span></div>\n    </div>\n    <div style="grid-column: 7 / 13; grid-row: 3; position: relative; cursor: pointer; overflow: hidden;" class="comp-photo-wrap" data-comp-index="4">\n      <img src="data:image/jpeg;base64," alt="Official CanSat 2026 final scoresheet showing Team 1049 Germany in 14th place with 78.18%" style="width:100%; aspect-ratio:16/9; object-fit:cover; object-position: center 18%; display:block; border: 0.5px solid var(--line);">\n      <div class="comp-photo-overlay"><span class="comp-photo-label">Official Scoresheet · Final Rankings</span></div>\n    </div>\n  </div>\n  <p style="font-size: 10px; color: rgba(136,136,128,0.5); letter-spacing: 0.06em; text-align: right; margin-top: 4px;">Click any photo to enlarge</p>\n</section>\n\n<!-- Competition lightbox -->\n<div id="comp-lightbox" style="display:none; position:fixed; inset:0; z-index:400; background:rgba(10,10,10,0.94); backdrop-filter:blur(14px); align-items:center; justify-content:center; padding:24px;" aria-hidden="true">\n  <div style="max-width:min(1100px,100%); width:100%; display:grid; grid-template-columns:minmax(0,1fr) 220px; gap:16px; max-height:calc(100vh - 48px);">\n    <div style="border:0.5px solid var(--line2); background:var(--bg2); display:flex; align-items:center; justify-content:center; min-height:0;">\n      <img id="comp-lb-img" src="" alt="" style="width:100%; max-height:calc(100vh - 120px); object-fit:contain; display:block;">\n    </div>\n    <div style="display:flex; flex-direction:column; gap:12px;">\n      <div id="comp-lb-caption" style="padding:14px; border:0.5px solid var(--line2); background:var(--bg3); color:var(--accent); font-size:10px; letter-spacing:0.08em; text-transform:uppercase; line-height:1.6;"></div>\n      <div style="display:grid; grid-template-columns:1fr 1fr; gap:8px;">\n        <button class="gallery-btn" type="button" id="comp-lb-prev">Prev</button>\n        <button class="gallery-btn" type="button" id="comp-lb-next">Next</button>\n        <button class="gallery-btn" type="button" id="comp-lb-close" style="grid-column:1/-1;">Close</button>\n      </div>\n      <div style="display:grid; grid-template-columns:repeat(2,1fr); gap:8px; overflow:auto;" id="comp-lb-thumbs"></div>\n    </div>\n  </div>\n</div>\n'

COMP_JS = '\n<script>\n(function() {\n  var compCaptions = [\n    \'Team Skybound \\u00b7 AAS, Monterey Virginia 2026\',\n    \'Ground Station \\u00b7 Pre-flight\',\n    \'Field Ops \\u00b7 Launch Day\',\n    \'Post-flight Hardware \\u00b7 After Recovery\',\n    \'Official Scoresheet \\u00b7 Final Rankings\'\n  ];\n  var compAlts = [\n    \'Team Skybound at CanSat 2026 in front of the AAS backdrop\',\n    \'Skybound ground station pre-flight with paraglider canopy\',\n    \'Field operations on launch day with orange CanSat shell\',\n    \'Post-flight hardware: orange shell, avionics, deployed paraglider\',\n    \'Official scoresheet \\u2014 Team 1049 Germany 14th place 78.18%\'\n  ];\n  var lightbox = document.getElementById(\'comp-lightbox\');\n  var lbImg = document.getElementById(\'comp-lb-img\');\n  var lbCaption = document.getElementById(\'comp-lb-caption\');\n  var lbThumbs = document.getElementById(\'comp-lb-thumbs\');\n  var compActive = 0;\n  var gridImgs = Array.from(document.querySelectorAll(\'[data-comp-index]\')).map(function(el){return el.querySelector(\'img\').src;});\n\n  function buildThumbs() {\n    lbThumbs.innerHTML = \'\';\n    gridImgs.forEach(function(src, i) {\n      var btn = document.createElement(\'button\');\n      btn.className = \'gallery-thumb-btn\' + (i === compActive ? \' is-active\' : \'\');\n      btn.type = \'button\';\n      btn.innerHTML = \'<img src="\' + src + \'" alt="\' + compAlts[i] + \'" style="width:100%;aspect-ratio:16/10;object-fit:cover;display:block;">\';\n      btn.addEventListener(\'click\', function(){setComp(i);});\n      lbThumbs.appendChild(btn);\n    });\n  }\n  function setComp(i) {\n    compActive = (i + gridImgs.length) % gridImgs.length;\n    lbImg.src = gridImgs[compActive];\n    lbImg.alt = compAlts[compActive];\n    lbCaption.textContent = compCaptions[compActive];\n    lbThumbs.querySelectorAll(\'.gallery-thumb-btn\').forEach(function(btn, idx){\n      btn.classList.toggle(\'is-active\', idx === compActive);\n    });\n  }\n  function openComp(i) {\n    compActive = i; buildThumbs(); setComp(i);\n    lightbox.style.display = \'flex\';\n    lightbox.setAttribute(\'aria-hidden\',\'false\');\n    document.body.style.overflow = \'hidden\';\n    document.getElementById(\'comp-lb-close\').focus();\n  }\n  function closeComp() {\n    lightbox.style.display = \'none\';\n    lightbox.setAttribute(\'aria-hidden\',\'true\');\n    document.body.style.overflow = \'\';\n  }\n  document.querySelectorAll(\'[data-comp-index]\').forEach(function(el){\n    el.addEventListener(\'click\', function(){openComp(Number(el.dataset.compIndex));});\n  });\n  document.getElementById(\'comp-lb-close\').addEventListener(\'click\', closeComp);\n  document.getElementById(\'comp-lb-prev\').addEventListener(\'click\', function(){setComp(compActive-1);});\n  document.getElementById(\'comp-lb-next\').addEventListener(\'click\', function(){setComp(compActive+1);});\n  lightbox.addEventListener(\'click\', function(e){if(e.target===lightbox)closeComp();});\n  document.addEventListener(\'keydown\', function(e){\n    if(lightbox.style.display!==\'flex\') return;\n    if(e.key===\'Escape\') closeComp();\n    if(e.key===\'ArrowLeft\') setComp(compActive-1);\n    if(e.key===\'ArrowRight\') setComp(compActive+1);\n  });\n})();\n</script>\n'

html = html.replace('</style>', COMP_CSS + '\n</style>', 1)
html = html.replace('<!-- ABOUT -->', COMP_SECTION + '\n<!-- ABOUT -->', 1)
html = html.replace('</body>', COMP_JS + '\n</body>', 1)

with open('index.html', 'w', encoding='utf-8') as f:
    f.write(html)

print("SUCCESS: index.html patched with CanSat 2026 competition results.")
